select importer.rezepte('[["hacktaetschli","gericht","Kalbshacktätschli mit Sugo","Kalbsfleisch, Mascarpone, Peterli","Hauptgang","Eigenes Rezept",10,180,null,["Zubereitung fehlt im Original: Schritte sind ein Vorschlag nach Standard-Hacktätschli.","Welches Gemüse? Angenommen: Zwiebel, Karotte, Sellerie je ein Drittel, fein gewürfelt.","Aufteilung der Butter (Gemüse dünsten / Braten) angenommen 50 / 50.","Salz, Pfeffer und Paniermehl hatten keine Menge.","Portion 2 × 90 g roh, ergibt aus dem Original 8 Portionen; hier auf 10 hochgerechnet."],[["sugo",80]],[[null,[["Weissbrot, entrindet",315,0,"≈ Original 250 g × 1.25"],["Vollmilch",250,0,"2.5 dl"]],[["Brot in Würfel schneiden und in der Milch einweichen.",null,null,5,15,null,false]]],[null,[["Gemüse (Zwiebel, Karotte, Sellerie)",250,2,"fein gewürfelt"],["Knoblauch",12,0,"≈ 2.5 Zehen"],["Butter",50,2,"Hälfte der Gesamtmenge"]],[["Gemüse und Knoblauch fein würfeln.",null,null,15,0,null,true],["In Butter weich dünsten und auskühlen lassen.","Kippbratpfanne",null,5,20,null,true]]],[null,[["Kalbshackfleisch",625,1,null],["Kalbsbrät",250,0,null],["Eier",125,0,"≈ 2.5 Stück"],["Mascarpone",100,0,null],["Peterli, gehackt",30,2,"≈ 1 Bund"],["Chiliflocken",2.5,0,"≈ 1 TL"],["Salz",22,2,"≈ 1.2 % der Masse"],["Pfeffer, gemahlen",3,2,null]],[["Mit Brot und Gemüse zu einer gleichmässigen Masse mischen.","Rührwerk",null,5,0,null,true],["Tätschli à 90 g formen und flach drücken.",null,null,20,0,null,true]]],[null,[["Paniermehl",100,2,"zum Wenden"],["Butter",50,2,"zum Braten"]],[["In Paniermehl wenden und beidseitig goldbraun anbraten.","Kippbratpfanne",180,10,0,null,true],["Fertig garen bis Kerntemperatur 72 °C.","Combi-Steamer",160,0,12,"Kern 72 °C",true]]]]],["curry","gericht","Kozhi Mappas","Mildes Hühner-Kokos-Curry","Hauptgang","Eigenes Rezept",10,300,null,["Original für 4 Portionen (600 g Poulet), hier auf 10 Portionen à 150 g Fleisch hochgerechnet.","Löffel- und Stückangaben in Gramm umgerechnet, bitte prüfen.","Salz und Pfeffer ohne Menge im Original.","Beilage (z.B. Basmatireis) fehlt; als eigene Komponente anlegen?"],[],[[null,[["Öl",50,0,"≈ 5 EL"],["Zwiebeln, in feinen Streifen",750,2,"≈ 5 Stück à 150 g"]],[["Zwiebeln unter Rühren anbraten.","Kippbratpfanne",null,10,0,null,false]]],[null,[["Chilipulver",2.5,0,"≈ 1¼ TL"],["Kurkuma",4,0,"≈ 1¼ TL"],["Koriandersamen, gemahlen",10,0,"≈ 5 TL"]],[["Gewürze darüberstreuen und kurz mitbraten.",null,null,2,0,null,false]]],[null,[["Pouletbrust, in 4 cm Würfeln",1500,1,null]],[["Fleisch zugeben und 3–4 Minuten anbraten, bis es Farbe hat.",null,null,5,0,null,false]]],[null,[["Kokosmilch",250,0,"erster Teil, 2.5 dl"],["Wasser",125,0,null],["Salz",22,2,null],["Pfeffer schwarz",2,2,null]],[["Angiessen und mit Salz und Pfeffer abschmecken.",null,null,3,0,null,false],["Zugedeckt bei schwacher Hitze köcheln lassen.",null,null,0,20,"Kern 72 °C",false]]],[null,[["Kokosmilch",750,0,"Rest, 7.5 dl"]],[["Zugeben und offen bei mittlerer Hitze weiterköcheln.",null,null,0,10,null,false]]],[null,[["Ghee",120,0,"≈ 10 EL"],["Zimtstangen",12,0,"≈ 5 Stück"],["Gewürznelken",1,0,"≈ 8 Stück"],["Senfkörner, braun",10,0,"≈ 2½ TL"]],[["Ghee erhitzen, Zimt, Nelken und Senfkörner 2 Minuten rösten und zum Curry geben.","Induktion",null,4,0,null,false]]]]],["quiche","gericht","Quiche aux Oignons","Zwiebel-Speck-Quiche","Apéro","Eigenes Rezept",10,140,null,["Kuchenteig: eigenes Grundrezept oder Zukauf? Rezept fehlt noch.","Zwiebelmenge (1 kleine Zwiebel) im Original eher knapp für eine Zwiebelquiche, bitte prüfen.","Gewürze ohne Menge im Original.","Für die Produktion: Blech- oder GN-Format und Stücke pro Blech festlegen."],[["kuchenteig",50]],[["Teig",[["Kuchenteig",500,0,"Komponente"],["Butter, weich",25,2,"zum Ausstreichen"]],[["Teig dünn ausrollen, Form ausbuttern und auslegen, Rand gut andrücken.",null,null,10,0,null,false],["Boden dicht einstechen und kühl stellen.",null,null,0,30,null,true]]],["Füllung",[["Zwiebeln",175,0,"≈ 2.5 kleine"],["Frühstücksspeck",100,0,null]],