ull],["Zitronengras, geputzt",45,2,"3 Stängel"],["Koriander",30,2,"1 Bund"],["Knoblauch",50,0,"10 Zehen"],["Chilis rot, gross",60,2,"4 Stück"],["Kaffir-Limettenblätter",2,0,"8 Blätter"]],[["Ingwer, Galgant, Zitronengras und Koriander grob hacken.",null,null,10,0,null,false],["Mit Knoblauch, Chilis und Limettenblättern zu einer feinen Paste zerkleinern.","Cutter",null,3,0,null,false]]],[null,[["Zucker",150,1,null]],[["Zucker in einem schweren Topf schmelzen und dunkel karamellisieren, nicht verbrennen lassen.","Induktion",null,8,0,null,false]]],[null,[["Apfelessig",105,0,"7 EL"],["Fischsauce",60,0,"4 EL"],["Sojasauce",60,0,"4 EL"]],[["Paste einrühren, aufkochen, Essig, Fisch- und Sojasauce zugeben, 1 Minute köcheln.",null,null,3,0,null,false],["Abkühlen und gekühlt lagern.","Schockkühler",null,0,30,null,true]]]]],["cheesecake","gericht","Basque Cheesecake","Gebrannter Käsekuchen ohne Boden","Dessert","ChefSteps (Nicholas Gavin)",20,140,null,["Portionen: 20 à 140 g angenommen; die Quelle rechnet mit 10–12 Portionen.","Rezept für Springform 23 cm: Umrechnung auf GN-Format und Backzeiten im Combi-Steamer testen.","Drehen der Form alle 10 Minuten ist im Combi-Steamer vermutlich nicht nötig; prüfen.","Varianten Schokolade und Kürbis sind in der Quelle beschrieben; bei Bedarf als Varianten anlegen.","Möglicher Dessert für Anlass A (Firmenjubiläum), dort ist das Dessert noch offen."],[],[["Masse",[["Doppelrahmfrischkäse",1360,1,null],["Zucker",450,0,null],["Weissmehl",65,0,null],["Salz",8,0,null],["Vollrahm 35 %",700,0,null],["Eier",450,0,"9 Stück"],["Vanilleextrakt",15,0,"optional"]],[["Frischkäse weich und streichfähig erwärmen.","Mikrowelle",null,5,0,null,false],["Zucker, Mehl und Salz mischen, mit Rahm, Eiern und Vanille glatt mixen, Frischkäse einarbeiten; möglichst wenig Luft einschlagen.","Stabmixer",null,10,0,null,false],["Masse auf 4 °C kühlen; hält so bis 3 Tage.","Kühlraum",null,0,120,"≤ 4 °C",false]]],["Backen",[],[["Form mit Alufolie und Backpapier auslegen, Masse durch ein Sieb einfüllen, Luftblasen entfernen.",null,null,15,0,null,false],["Erste Backphase: Oberfläche kräftig bräunen.","Combi-Steamer",216,5,30,null,true],["Zweite Backphase, bis der Kern 46–52 °C erreicht und die Mitte noch wackelt.","Combi-Steamer",149,0,40,"Kern 46–52 °C",false],["Bei Raumtemperatur nachziehen lassen (Kern steigt auf 66 °C), dann mindestens 8 Stunden kühlen.","Kühlraum",null,0,580,"Kern 66 °C",false],["Mit warmem Messer portionieren.",null,null,10,0,null,false]]]]],["pate","gericht","Imfoiessible Pâté","Vegane Mousse nach Art Foie gras","Apéro / Vorspeise","ChefSteps (Matthew Woolen)",12,60,null,["Portionen: 12 à 60 g angenommen; die Quelle nennt 8–12 Portionen.","Gellan (low-acyl und high-acyl) im Artikelstamm anlegen, Lieferant klären.","Kochend heiss mixen: Arbeitssicherheit (Deckel, Tuch) in der Einführung erwähnen.","«Sweet Spice» ist eine Mischung der Quelle; eigene Gewürzmischung festlegen.","Haltbarkeit laut Quelle 1 Woche, mit Fettdeckel 2–3 Wochen: HACCP-Wert festlegen."],[],[[null,[["Cashewkerne, roh",150,1,null]],[["In kaltem Wasser mindestens 2 Stunden, besser über Nacht einweichen, abgiessen.",null,null,0,120,null,false]]],[null,[["Kokosöl, raffiniert",15,0,null],["Schalotten, in Scheiben",90,0,"2 Stück"],["Champignons, in Scheiben",50,0,null],["Knoblauch, in Scheiben",12,0,"2 Zehen"],["Cognac",110,0,null]],[["Schalotten, Champignons und Knoblauch in Kokosöl zugedeckt weich dünsten.","Induktion",null,12,0,null,false],["Mit Cognac ablöschen und um die Hälfte reduzieren.",null,null,2,0,null,false]]],[null,[["Wasser",275,0,null],["Kokosöl, raffiniert",70,0,null],["Miso, hell",25,0,null],["Tomatenpüree",15,0,null],["Salz",8,0,null],["Gewürzmischung süss",2.5,2,"«Sweet Spice» der Quelle"],["Pfeffer schwarz",1.5,0,null]],[["Cashews und Würzzutaten zugeben, aufkochen und 30 Sekunden kochen.",null,null,3,0,null,false]]],[null,[["Gellan low-acyl",1.5,0,null],["Gellan high-acyl",0.4,0,null]],[["Heiss glatt mixen, Gellan bei laufendem Mixer zugeben, bis 93–100 °C weitermixen. (Temperatur: 93–100 °C)","Hochleistungsmixer",93,3,0,null,false]]],[null,[["Pflanzenfett für Fettdeckel",50,2,"optional"]],[["Sofort in Gläser abfüllen, Oberfläche abdecken oder mit Fettdeckel versiegeln.",null,null,5,0,null,false],["Kühlen, bis die Masse gestockt ist.","Kühlraum",null,0,60,"≤ 7 °C",false]]]]],["meatloaf","gericht","Sous-vide-Hackbraten","Mit Zwiebelkonfit, Pilzen und Glasur (Modernist Meatloaf)","Hauptgang","ChefSteps (Kyl Haselbauer)",6,200,null,["Portionen: 6 à 200 g angenommen; die Quelle nennt 4–6 Portionen.","Gellan und Natriumhexametaphosphat: Lieferant klären. Die Quelle beschreibt auch eine einfache Glasur ohne diese Zusätze.","Sous-vide im Combi-Steamer statt Wasserbad: Garzeit für eine Rolle von 8 cm Durchmesser prüfen.","Für grosse Mengen: Terrinenform oder GN statt Folienrolle?"],[],[["Panade",[["Sauerteigbrot, gewürfelt",50,0,null],["Vollmilch",50,0,null]],[["Brotwürfel mit Milch mischen und mindestens 1 Stunde kühl ziehen lassen.",null,null,3,60,null,false]]],["Zwiebelkonfit",[["Rotwein, trocken",250,0,null],["Zwiebeln, süss, gewürfelt",190,0,"1 Stück"]],[["Zugedeckt 15 Minuten kochen, offen zu Konfit einkochen und kühlen.","Induktion",null,7,45,null,false]]],["Pilze",[["Champignons, geviertelt",400,0,null],["Olivenöl",28,0,null],["Salz",3,0,null],["Pfeffer schwarz",1,0,null]],[["Mischen und rösten, bis sie trocken und leicht gebräunt sind; kühlen.","Combi-Steamer",218,5,48,null,false]]],["Glasur",[["Ketchup",300,0,null],["Rindsbouillon",200,0,null],["Rohrzucker, hell",150,0,null],["Worcestershire-Sauce",25,0,null],["Salz",4,0,null],["Paprika edelsüss",3,0,null],["Pfeffer schwarz",2,0,null],["Natriumhexametaphosphat",1,0,null],["Gellan low-acyl",3,0,null],["Gelatine",33,0,"10 Blatt"]],[["Alles ausser Gellan und Gelatine aufkochen und mixen, Gellan einmixen bis 93 °C, flach ausgiessen und fest werden lassen.","Hochleistungsmixer",93,10,60,null,false],["Glasur fein pürieren, auf 60 °C erwärmen,