false]]],[null,[["Butter, weich",50,0,null]],[["Butter einarbeiten, bis sich der Teig vom Kessel löst.","Knetmaschine",null,2,6,null,false],["Bei 24 °C gären lassen bis doppeltes Volumen, zusammenschlagen, nochmals verdoppeln.","Gärschrank",null,0,240,null,false],["In 2 × 330 g teilen, ausrollen und zweimal falten, 30 Minuten ruhen lassen, straff aufrollen.",null,null,20,30,null,false],["In der gefetteten Form mit Deckel gären, bis der Teig drei Viertel der Höhe erreicht.","Gärschrank",null,0,150,null,false],["Mit Deckel backen bis Kern 90 °C.","Combi-Steamer",177,0,40,"Kern 90 °C",true],["Ausformen und auf dem Gitter auskühlen.",null,null,0,120,null,false]]]]],["shiopan","komponente","Shio Pan","Japanisches Salzbrötchen mit Butterkern","Gebäck","ChefSteps (Tim Chin)",null,null,760,["US-Mehle (Bread flour, Cake flour) durch Schweizer Sorten ersetzen, z.B. Weissmehl 550 und Feinmehl; testen.","Brezelsalz: Lieferant klären, sonst Fleur de Sel.","Ergibt 8 Stück à ca. 95 g angenommen.","Haltbarkeit laut Quelle: 2 Tage bei Raumtemperatur, 1 Woche gekühlt, 3 Monate tiefgekühlt."],[],[["Butterkern",[["Butter, kalt",120,0,"8 × 15 g"]],[["In 8 Stücke à 15 g schneiden und anfrieren.","Tiefkühler",null,5,10,null,false]]],["Tangzhong",[["Wasser",120,0,null],["Weissmehl Typ 550",32,0,null],["Eis",125,0,null]],[["Wasser und Mehl zu einem Gel kochen, mit dem Eis auf 2–7 °C abkühlen.","Induktion",null,5,0,null,false]]],["Teig",[["Weissmehl Typ 550",240,1,null],["Feinmehl (Cake flour)",75,2,null],["Magermilchpulver",20,0,null],["Instanthefe",5,0,null]],[["Trockenes mischen, Tangzhong zugeben, 4 Minuten mischen und 15 Minuten ruhen lassen.","Knetmaschine",null,2,19,null,false]]],[null,[["Zucker",20,0,null],["Salz",6,0,null],["Butter, kalt",30,0,null]],[["Zucker und Salz einarbeiten, dann die Butter; kneten, bis der Fenstertest gelingt.","Knetmaschine",null,3,15,null,false],["Gären lassen bis doppeltes Volumen.","Gärschrank",null,0,75,null,false],["In 80-g-Stücke teilen, rund formen, 